package com.priperi;
import java.security.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;
/** Standard PBKDF2-HMAC-SHA256/AES-256-GCM. Words and app password are both required. */
final class TransferCipher {
 static final int ITERATIONS=600000,MAX_PLAIN=24000;
 private static final byte[] MAGIC="PRIPTC01".getBytes(StandardCharsets.US_ASCII);
 static String hash(byte[] value)throws GeneralSecurityException{byte[] digest=MessageDigest.getInstance("SHA-256").digest(value);StringBuilder s=new StringBuilder();for(byte b:digest)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static String lookup(byte[] entropy)throws GeneralSecurityException{if(entropy.length!=32)throw new GeneralSecurityException("Invalid transfer words");return hash(join("priperi-transfer-lookup-v1\n".getBytes(StandardCharsets.US_ASCII),entropy));}
 static byte[] key(byte[] entropy,char[] password,byte[] salt)throws GeneralSecurityException{if(entropy.length!=32||salt.length!=16||password==null||password.length<12||password.length>72)throw new GeneralSecurityException("Enter the current app password.");byte[] kdfSalt=MessageDigest.getInstance("SHA-256").digest(join("priperi-transfer-key-v1\n".getBytes(StandardCharsets.US_ASCII),entropy,salt));PBEKeySpec spec=new PBEKeySpec(password,kdfSalt,ITERATIONS,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();Arrays.fill(kdfSalt,(byte)0);}}
 static String seal(byte[] plain,byte[] entropy,char[] password)throws GeneralSecurityException{if(plain.length==0||plain.length>MAX_PLAIN)throw new GeneralSecurityException("Transfer identity is too large.");byte[] salt=new byte[16],iv=new byte[12];SecureRandom random=new SecureRandom();random.nextBytes(salt);random.nextBytes(iv);byte[] key=key(entropy,password,salt),header=join(MAGIC,salt,iv);try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));cipher.updateAAD(join(header,lookup(entropy).getBytes(StandardCharsets.US_ASCII)));return Base64.getEncoder().encodeToString(join(header,cipher.doFinal(plain)));}finally{Arrays.fill(key,(byte)0);}}
 static byte[] open(String capsule,byte[] entropy,char[] password)throws GeneralSecurityException{if(capsule==null||capsule.length()>32768)throw new GeneralSecurityException("Invalid transfer package");byte[] bytes;try{bytes=Base64.getDecoder().decode(capsule);}catch(IllegalArgumentException e){throw new GeneralSecurityException("Invalid transfer package",e);}if(bytes.length<53||bytes.length>MAX_PLAIN+52||!Base64.getEncoder().encodeToString(bytes).equals(capsule)||!MessageDigest.isEqual(MAGIC,Arrays.copyOf(bytes,8)))throw new GeneralSecurityException("Invalid transfer package");byte[] key=key(entropy,password,Arrays.copyOfRange(bytes,8,24));try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,Arrays.copyOfRange(bytes,24,36)));cipher.updateAAD(join(Arrays.copyOf(bytes,36),lookup(entropy).getBytes(StandardCharsets.US_ASCII)));return cipher.doFinal(bytes,36,bytes.length-36);}finally{Arrays.fill(key,(byte)0);Arrays.fill(bytes,(byte)0);}}
 private static byte[] join(byte[]... arrays){int n=0;for(byte[] a:arrays)n+=a.length;byte[] out=new byte[n];int p=0;for(byte[] a:arrays){System.arraycopy(a,0,out,p,a.length);p+=a.length;}return out;}
 private TransferCipher(){}
}
